            'data_link_text_regulation_kb' => 'قاعدة معارف التنظيم',
            'data_link_text_research_index' => 'فهرس الأبحاث الكامل',
            'data_link_text_broker_review' => 'مراجعة وسيط',
            'data_link_text_cost_calculator' => 'حاسبة التكلفة',
            'data_link_text_regulation_checker' => 'فاحص التنظيم',
            'data_link_text_editorial_policy' => 'السياسة التحريرية',
            'data_p_dataset_1' => '%1$s وسيطًا، تم تقييم كل منهم وفق نفس المعايير المعلنة من تسع فئات -- التنظيم، التكلفة، الرسوم غير المرتبطة بالتداول، المنصات، التنفيذ، تشكيلة المنتجات، الإيداع/السحب، الشفافية، وسجل الأداء -- بحيث تعني الدرجة نفس الشيء في أي صفحة تظهر فيها. وحيثما تعذّر علينا تأكيد حقل ما بشكل مستقل، نذكر ذلك بدلاً من التخمين؛ وينعكس ذلك مباشرة في %2$s وفي تصنيف الموثوقية الظاهر بجانب كل حقيقة في %3$s.',
            'data_p_dataset_2' => 'تُغذّي مجموعة البيانات نفسها أيضًا %1$s من %2$s المنتقاة بعناية و%3$s من %4$s المكتوبة يدويًا. وتستطيع أداة المقارنة التفاعلية نفسها مطابقة أي وسيطين من بين %5$s وسيطًا تم بحثهم عند الطلب؛ كما تحصل %6$s من تلك الأزواج -- أي كل توليفة ممكنة بين أفضل %7$s وسيطًا لدينا من حيث الترتيب -- على صفحتها الخاصة المفهرسة والقابلة للربط بدلاً من أن توجد فقط داخل الأداة.',
            'data_p_regulator' => '%1$s جهة تنظيمية -- CySEC وFCA وهيئة سيشل FSA وASIC وFSCA وDFSA وFMA في نيوزيلندا وMAS في سنغافورة وCMA في كينيا -- لكل منها %2$s خاصة بها: الولاية القضائية، قواعد الرافعة المالية، نظام التعويض (أو غيابه الصريح)، إجراءات الشكاوى، السجل الرسمي للتحقق من أي شركة، وقائمة حية بمن يحمل هذا الترخيص حاليًا من الوسطاء الذين بحثناهم. وإجمالًا عبر الجهات التسع، يحمل الوسطاء الذين بحثناهم %3$s ترخيصًا تنظيميًا مؤكدًا فيما بينهم -- حيث يُحتسب الوسيط الحامل لتراخيص من ثلاث جهات تنظيمية ثلاث مرات في هذا الإجمالي، لأن الهدف هو إظهار الانتشار الفعلي وليس نسبة الوسطاء إلى الجهات التنظيمية. وحيثما يكثر الخلط بين جهتين تنظيميتين -- الكيان القانوني لوسيط، التمييز بين الفئة الأولى والجهات الخارجية، سقف تعويض محدد -- تغطي %4$s لدينا %5$s مباشرة.',
            'data_p_research' => '%1$s حتى الآن، تم بناء كل منها بالكامل من مجموعة بيانات هذا الموقع الخاصة التي تضم %2$s وسيطًا -- وليست استطلاعًا من جهة خارجية، ولا بيانًا صحفيًا، بل إحصاءً مباشرًا لشيء موجود بالفعل في أبحاثنا. ويوضح كل تقرير منهجيته الخاصة سلفًا: حجم العينة، تاريخ آخر مراجعة للبيانات الأساسية، كيفية تعريفنا لحقيقة "مؤكدة"، كيفية التعامل مع البيانات المفقودة، وتسلسل المصادر المستخدم لتأكيد كل رقم. راجع %3$s. وهذه مكتبة صغيرة عن قصد ومتنامية -- حفنة من التقارير الممتازة والقابلة للاستشهاد بها، وليست تقارير تُنشأ آليًا لكل تقاطع ممكن من مجموعة البيانات.',
            'data_p_confidence' => 'ليست كل حقيقة في هذه المجموعة موثّقة بنفس الجودة، ولا نعرضها كما لو كانت كذلك. تحمل الحقائق الفردية في صفحات مراجعات الوسطاء شارة موثوقية عالية أو متوسطة أو منخفضة تُحتسب من نفس لغة التحوط التي تستخدمها ملاحظات أبحاثنا بالفعل -- فـ"مؤكَّد عبر الصفحة المنشورة للوسيط نفسه" يُصنَّف بشكل مختلف عن "المصادر متضاربة" أو "غير مؤكَّد بشكل مستقل". وتُترك الحقيقة التي لا تحمل أي إشارة في أي الاتجاهين دون تصنيف بدلاً من منحها درجة متوسطة مُخمَّنة. راجع قسم التحليل المعمّق في أي %1$s لرؤية ذلك عمليًا.',
            'data_p_tools' => 'تعمل ثلاث أدوات تفاعلية مباشرة على نفس مجموعة البيانات بدلاً من نسخة منفصلة منها: %1$s (يُصفّي مجموعتنا الكاملة من الوسطاء الذين بحثناهم وفق إجاباتك الخاصة)، و%2$s (يقدّر تكلفة السبريد السنوية الخاصة بك لدى كل وسيط لديه سبريد مؤكَّد)، و%3$s (الملف التنظيمي الكامل لأي وسيط تم بحثه). ولا تحتفظ أي من الأدوات الثلاث ببياناتها الخاصة بشكل منفصل -- فأي تغيير في سجل وسيط يُحدِّث الأدوات الثلاث تلقائيًا.',
            'data_p_keeping_current' => 'البيانات تتغير، ونحاول ألا نترك الموقع يتخلف عنها بصمت. %1$s هو سجل مؤرَّخ لكل وسيط على حدة يوثّق متى تغيّرت حقيقة منشورة فعليًا -- تحديث سبريد، رقم ترخيص جديد، إضافة أو إزالة منصة -- وليس إعلانًا تسويقيًا. أما الأخطاء الجوهرية التي نكتشفها بعد النشر فتُسجَّل ولا تُعدَّل بصمت، في %2$s. وتوجد سياستنا الكاملة بشأن المصادر واستخدام الذكاء الاصطناعي والتقييم في %3$s.',
